43	const PROCESSING_FEE = 5;
44	
45	/**
46	 * Rates are kept as exact numerator/denominator fractions rather than float
47	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
48	 * only the final premium is rounded.
49	 */
50	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	};
59	
60	export const runScenario = (scenario: Scenario): ScenarioResult => {
61	  const quote = scenario.steps[0] as QuoteStep;
62	  const basePremium = quote.items.reduce(
63	    (sum, item) => sum + BASE_PREMIUMS[item.type],
64	    0,
65	  );
66	  const firstInsuranceSurcharge = percent(
67	    basePremium,
68	    FIRST_INSURANCE_SURCHARGE_PERCENT,
69	  );
70	  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
71	  return { results: [{ premium: Math.ceil(premium) }] };
72	};
